window.AUTH=window.AUTH||{};window.AUTH["19-1189"]={"d":"19-1189","id":"2020/19-1189","n":"BP P.L.C. v. Mayor and City Council of Baltimore","briefs":[{"k":"petitioner","label":"Brief of petitioners BP p.l.c., et al.","date":"2020-11-16","url":"https://www.supremecourt.gov/DocketPDF/19/19-1189/160813/20201116134527686_19-1189_petbr.pdf","side":"pet","n":111},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2020-11-23","url":"https://www.supremecourt.gov/DocketPDF/19/19-1189/161562/20201123144559087_19-1189tsacUnitedStates.pdf","side":"us","n":69},{"k":"respondent","label":"Brief of respondent Mayor and City Council of Baltimore","date":"2020-12-16","url":"https://www.supremecourt.gov/DocketPDF/19/19-1189/163961/20201216153254492_19-1189%20BP%20plc%20v.%20Baltimore%20Brief%20of%20Respondent.pdf","side":"res","n":52},{"k":"reply","label":"Reply of petitioners BP p.l.c., et al.","date":"2021-01-08","url":"https://www.supremecourt.gov/DocketPDF/19/19-1189/165678/20210108111947342_19-1189_meritsreply.pdf","side":"pet","n":63}],"opinion":"https://www.supremecourt.gov/opinions/20pdf/593us1r35_i425.pdf","tr":true,"items":[{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"by":{"0":"35","3":"9"},"q":[{"src":"brief","b":0,"text":"[i]t is impossible to assert with any degree of assurance that congressional failure to act represents affirmative congressional approval of the [prior judicial] interpretation.","cite":"532 U.S. 275, 292"},{"src":"brief","b":3,"text":"affirmative congressional approval of [a prior judicial] interpretation.","cite":"532 U.S. 275, 292"},{"src":"argument","who":"Mr. Shanmugam","text":"As Justice Scalia explained in his opinion for the Court in Alexander versus Sandoval, the relevant inquiry is whether one can \"assert with any degree of assurance that congressional failure to act represents affirmative congressional approval of the court's statutory interpretation.\" Here, there is simply no reason to believe that Congress was preferring the unreasoned decisions of some courts of appeals construing this statute over the reasoned decisions of this Court construing materially identical ones, particularly given the technical nature of the 2011 amendment."}]},{"t":"case","label":"American Electric Power Co. v. Connecticut","cite":"564 U.S. 410","y":2011,"id":"2010/10-174","sc":1,"by":{"0":"passim","1":"26, 27","3":"19"},"q":[{"src":"brief","b":1,"text":"the scope, nature, legal incidents and consequences of the relation between persons in service and the Government are fundamentally derived from federal sources and governed by federal authority.","cite":"564 U.S. 410"}]},{"t":"case","label":"Armstrong v. Exceptional Child Center, Inc.","cite":"135 S. Ct. 1378","y":2015,"id":"2014/14-15","sc":1,"by":{"0":"34"}},{"t":"case","label":"Avco Corp. v. Machinists","cite":"390 U.S. 557","y":1968,"id":"1967/445","sc":1,"by":{"0":"45"}},{"t":"case","label":"Azar v. Allina Health Services","cite":"139 S. Ct. 1804","y":2019,"id":"2018/17-1484","sc":1,"by":{"0":"32","1":"30"},"q":[{"src":"brief","b":1,"text":"Congress, which—unlike the courts—is both qualified and constitutionally entitled to weigh the costs and benefits of different approaches and make the necessary policy judgment.","cite":"139 S. Ct. 1804, 1816"}]},{"t":"case","label":"Banco Nacional de Cuba v. Sabbatino","cite":"376 U.S. 398","y":1964,"id":"1963/16","sc":1,"by":{"0":"42"},"q":[{"src":"brief","b":0,"text":"relationships with other members of the international community.","cite":"376 U.S. 398, 425, 426"}]},{"t":"case","label":"Behrens v. Pelletier","cite":"516 U.S. 299","y":1996,"id":"1995/94-1244","sc":1,"by":{"0":"36","2":"5, 13"},"q":[{"src":"brief","b":2,"text":"frivolous double jeopardy claims in order to bring more serious, but otherwise nonappealable questions","cite":"516 U.S. at 312"},{"src":"argument","who":"Mr. Sher","text":"To the contrary, this Court has -- has frequently disentangled issues and made clear in cases like Swint and Abney and Behrens, all of which Petitioners ignore, that you cannot use an -- an appealable issue as a ticket for multi-issue appeals that are not allowed."},{"src":"argument","who":"Mr. Sher","text":"And, in Behrens, a wrongful discharge -- discharge case, Justice Scalia explained that a single order could be reviewed with respect to the issue of denying qualified immunity but not with respect to determinations of evidentiary sufficiency."}]},{"t":"case","label":"Bell v. Hood","cite":"327 U.S. 678","y":1946,"id":"scdb/1945-042","sc":1,"by":{"0":"36","1":"30","2":"7, 28, 29"},"q":[{"src":"argument","who":"Mr. Shanmugam","text":"So I think that an alternative option that would be available to the Court would be to say, on a ground much like that that the Court adopted in Bell versus Hood, that where the federal officer or civil rights ground is frivolous, there is no appellate jurisdiction."},{"src":"argument","who":"Justice Kagan","text":"Shanmugam, when you were talking with the Chief Justice and Justice Thomas about frivolous cases, you seemed to want to rely on sanctions rather than a -- a kind of Bell v."},{"src":"argument","who":"Mr. Shanmugam","text":"And if the Court thinks that sanctions and fee awards would be insufficient in this context, knowing that that is what the Court ordinarily relies on to deter improper conduct by litigants, I think that the Court could adopt a Bell versus Hood-like rule."}]},{"t":"case","label":"BMW of North America v. Gore","cite":"517 U.S. 559","y":1996,"id":"1995/94-896","sc":1,"by":{"0":"39","3":"19"},"q":[{"src":"brief","b":0,"text":"impos[e] its regulatory policies on the entire Nation.","cite":"517 U.S. 559, 585"},{"src":"brief","b":3,"text":"impos[e] its regulatory policies on the entire Nation.","cite":"517 U.S. 559, 585"}]},{"t":"case","label":"Board of County Commissioners v. Suncor Energy (U.S.A.) Inc.","cite":"965 F.3d 792","y":2020,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/965/792/","by":{"0":"7","1":"15, 16"},"q":[{"src":"brief","b":1,"text":"contemplate the situation in which removal is done pursuant to [the civilrights removal statute or federal-officer removal statute] and other grounds.","cite":"965 F.3d 792, 805"}]},{"t":"case","label":"Brill v. Countrywide Home Loans, Inc.","cite":"427 F.3d 446","y":2005,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/427/446/","by":{"0":"25"}},{"t":"case","label":"Carlsbad Technology, Inc. v. HIF Bio, Inc.","cite":"556 U.S. 635","y":2009,"id":"2008/07-1437","sc":1,"by":{"0":"17","3":"6"}},{"t":"case","label":"Caterpillar, Inc. v. Williams","cite":"482 U.S. 386","y":1987,"id":"1986/86-526","sc":1,"by":{"0":"44","3":"20"},"q":[{"src":"brief","b":0,"text":"a federal question is presented on the face of the plaintiff’s properly pleaded complaint.","cite":"482 U.S. 386, 392"}]},{"t":"case","label":"Chambers v. NASCO, Inc.","cite":"501 U.S. 32","y":1991,"id":"1990/90-256","sc":1,"by":{"0":"35, 36"}},{"t":"case","label":"City of Columbus v. Ours Garage & Wrecker Service, Inc.","cite":"536 U.S. 424","y":2002,"id":"2001/01-419","sc":1,"by":{"0":"33"},"q":[{"src":"brief","b":0,"text":"[a] congressional decision to enact both a general policy that furthers a particular goal and a specific exception that might tend against that goal does not invariably call for the narrowest possible construction of the exception.","cite":"536 U.S. 424, 440"}]},{"t":"case","label":"City of Greenwood v. Peacock","cite":"384 U.S. 808","y":1966,"id":"1965/471","sc":1,"by":{"0":"27"},"q":[{"src":"brief","b":0,"text":"any federal law providing for equal civil rights.","cite":"384 U.S. 808, 824"}]},{"t":"case","label":"City of Milwaukee v. Illinois","cite":"451 U.S. 304","y":1981,"id":"1980/79-408","sc":1,"by":{"0":"39","1":"27","2":"42, 45","3":"20"},"q":[{"src":"brief","b":1,"text":"if federal common law exists, it is because state law cannot be used.","cite":"451 U.S. 304, 313 n.7"},{"src":"brief","b":3,"text":"if federal common law exists, it is because state law cannot be used.","cite":"451 U.S. 304, 313 n.7"}]},{"t":"case","label":"City of Oakland v. BP p.l.c.","cite":"960 F.3d 570","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/960/570/","by":{"0":"7"}},{"t":"case","label":"City of Walker v. Louisiana","cite":"877 F.3d 563","y":2017,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/877/563/","by":{"0":"25"}},{"t":"case","label":"Coffey v. Freeport McMoran Copper & Gold","cite":"581 F.3d 1240","y":2009,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/581/1240/","by":{"0":"25"}},{"t":"case","label":"County of San Mateo v. Chevron Corp.","cite":"960 F.3d 586","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/960/586/","by":{"0":"7"}},{"t":"case","label":"Dahda v. United States","cite":"138 S. Ct. 1491","y":2018,"id":"2017/17-43","sc":1,"by":{"0":"24"}},{"t":"case","label":"Deckert v. Independence Shares Corp.","cite":"311 U.S. 282","y":1940,"id":"scdb/1940-011","sc":1,"by":{"0":"22"}},{"t":"case","label":"Department of Revenue v. ACF Industries, Inc.","cite":"510 U.S. 332","y":1994,"id":"1993/92-74","sc":1,"by":{"0":"31, 32"}},{"t":"case","label":"EPA v. EME Homer City Generation, L.P.","cite":"572 U.S. 489","y":2014,"id":"2013/12-1182","sc":1,"by":{"0":"28"}},{"t":"case","label":"Erie Railroad Co. v. Tompkins","cite":"304 U.S. 64","y":1938,"id":"1900-1940/304us64","sc":1,"by":{"0":"38, 40"}},{"t":"case","label":"Exxon Mobil Corp. v. Allapattah Services, Inc.","cite":"545 U.S. 546","y":2005,"id":"2004/04-70","sc":1,"by":{"0":"17"}},{"t":"case","label":"Exxon Shipping Co. v. Baker","cite":"554 U.S. 471","y":2008,"id":"2007/07-219","sc":1,"by":{"0":"17, 24"}},{"t":"case","label":"Federated Department Stores, Inc. v. Moitie","cite":"452 U.S. 394","y":1981,"id":"1980/79-1517","sc":1,"by":{"0":"44"},"q":[{"src":"brief","b":0,"text":"determine whether the real nature of the claim is federal, regardless of plaintiff’s characterization.","cite":"452 U.S. 394, 397 n.2"}]},{"t":"case","label":"Florida Lime & Avocado Growers, Inc. v. Jacobsen","cite":"362 U.S. 73","y":1960,"id":"1959/49","sc":1,"by":{"0":"23","1":"19"},"q":[{"src":"brief","b":1,"text":"over all grounds of attack against the statute,","cite":"362 U.S. 73, 84"}]},{"t":"case","label":"Food Marketing Institute v. Argus Leader Media","cite":"139 S. Ct. 2356","y":2019,"id":"2018/18-481","sc":1,"by":{"0":"33","3":"3"},"q":[{"src":"brief","b":0,"text":"normally have no license to give [statutory] exemption[s] anything but a fair reading.","cite":"139 S. Ct. 2356, 2366"},{"src":"brief","b":3,"text":"normally have no license to give [statutory] exemption[s] anything but a fair reading.","cite":"139 S. Ct. 2356, 2366"}]},{"t":"case","label":"Fourth Estate Public Benefit Corp. v. Wall-Street.com, LLC","cite":"139 S. Ct. 881","y":2019,"id":"2018/17-571","sc":1,"by":{"0":"32","3":"3"},"q":[{"src":"argument","who":"Mr. Sher","text":"Well, Your Honor, the assertion of federal officer jurisdiction in this case, which was rejected by now four circuits, including the Fourth Circuit below, was really based on doctrines that have been soundly disapproved and rejected by this Court, ranging from government regulation and supervision to a -- a lack of connection between the conduct that's the basis of the tort, which is misrepresentation and a campaign of deception and denial, and any relationship to the government, much less any appropriate federal interest in promoting those kinds of lies and deceit."},{"src":"argument","who":"Mr. Sher","text":"The -- the tort that is concerned -- that is -- that we're concerned with -- and the Fourth Circuit addressed this in detail in its opinion, as did Judge Hollander in the district court; it's on pages 21a and 22a of the -- of the circuit court's opinion in the -- in the record -- pointed out that the -- that the conduct complained of is fraud, deception, denial, and disinformation --"},{"src":"argument","who":"Mr. Sher","text":"In fact, it was the Fourth Circuit in a 1969 opinion called House v. Dorsey, 408 F.2d 1008, it was a 1443 removal solely. The court of appeals looked at it and held that the removing party did not qualify under 1443 and dismissed for lack of jurisdiction."}]},{"t":"case","label":"Franchise Tax Board v. Construction Laborers Vacation Trust","cite":"463 U.S. 1","y":1983,"id":"1982/82-695","sc":1,"by":{"0":"44","3":"21"},"q":[{"src":"brief","b":0,"text":"a plaintiff may not defeat removal by omitting to plead necessary federal questions.","cite":"463 U.S. 1, 22"},{"src":"brief","b":3,"text":"may not defeat removal by omitting to plead necessary federal questions in a complaint.","cite":"463 U.S. 1, 22"}]},{"t":"case","label":"Franchise Tax Board v. Hyatt","cite":"139 S. Ct. 1485","y":2019,"id":"2018/17-1299","sc":1,"by":{"0":"39"}},{"t":"case","label":"Georgia v. Tennessee Copper Co.","cite":"206 U.S. 230","y":1907,"id":"scdb/1906-076","sc":1,"by":{"0":"40"}},{"t":"case","label":"Goosby v. Osser","cite":"409 U.S. 512","y":1973,"id":"1972/71-6316","sc":1,"by":{"0":"36"}},{"t":"case","label":"Healy v. Beer Institute, Inc.","cite":"491 U.S. 324","y":1989,"id":"1988/88-449","sc":1,"by":{"0":"39"}},{"t":"case","label":"Illinois v. City of Milwaukee","cite":"406 U.S. 91","y":1972,"id":"1971/49_orig","sc":1,"by":{"0":"6, 39, 40"},"q":[{"src":"brief","b":0,"text":"an overriding federal interest in the need for a uniform rule of decision,","cite":"406 U.S. 91, 105 n.6"}]},{"t":"case","label":"International Paper Co. v. Ouellette","cite":"479 U.S. 481","y":1987,"id":"1986/85-1233","sc":1,"by":{"0":"9, 40, 41","1":"27"},"q":[{"src":"brief","b":0,"text":"should be resolved by reference to federal common law.","cite":"479 U.S. 481, 488"},{"src":"brief","b":0,"text":"do indirectly what they could not do directly—regulate the conduct of out-of-state sources.","cite":"479 U.S. at 495"},{"src":"brief","b":1,"text":"pursuant to the law of the source State.","cite":"479 U.S. 481, 492, 497"}]},{"t":"case","label":"Jennings v. Stephens","cite":"574 U.S. 271","y":2015,"id":"2014/13-7211","sc":1,"by":{"0":"24"}},{"t":"case","label":"Johnson v. Mississippi","cite":"421 U.S. 213","y":1975,"id":"1974/73-1531","sc":1,"by":{"0":"27"},"q":[{"src":"brief","b":0,"text":"providing for specific civil rights stated in terms of racial equality","cite":"421 U.S. 213, 219"}]},{"t":"case","label":"Juliana v. United States","cite":"947 F.3d 1159","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/947/1159/","by":{"0":"29"}},{"t":"case","label":"Kansas v. Colorado","cite":"206 U.S. 46","y":1907,"id":"scdb/1906-063","sc":1,"by":{"0":"40"}},{"t":"case","label":"Lewis v. BT Investment Managers, Inc.","cite":"447 U.S. 27","y":1980,"id":"1979/79-45","sc":1,"by":{"0":"23"}},{"t":"case","label":"Lightfoot v. Cendant Mortgage Corp.","cite":"137 S. Ct. 553","y":2017,"id":"2016/14-1055","sc":1,"by":{"0":"34","1":"22","3":"10"},"q":[{"src":"brief","b":1,"text":"would have surveyed the jurisprudential landscape and necessarily concluded that the courts had already settled the question.","cite":"137 S. Ct. 553, 564"}]},{"t":"case","label":"Lu Junhong v. Boeing Co.","cite":"792 F.3d 805","y":2015,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/792/805/","by":{"0":"passim","1":"24, 25","2":"9, 37, 40"},"q":[{"src":"brief","b":0,"text":"To say that a district court’s ‘order’ is reviewable is to allow appellate review of the whole order, not just of particular issues or reasons.","cite":"792 F.3d 805, 811"},{"src":"brief","b":0,"text":"authorized to take the time necessary to determine the right forum.","cite":"792 F.3d at 813"},{"src":"brief","b":1,"text":"[t]he marginal delay from adding an extra issue to a case where the time for briefing, argument, and decision has already been accepted is likely to be small.","cite":"792 F.3d 805, 813"},{"src":"brief","b":2,"text":"all they really want is a hook to allow appeal of some different subject.","cite":"792 F.3d 805, 813"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"`order remanding a case to the State court from which it was removed pursuant to section 1442 or 1443.'","cite":"792 F. 3d 805, 811"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"marginal delay from adding . . . extra issue[s] to a case where the time for briefng, argument, and decision has already been accepted is likely to be small.","cite":"792 F. 3d, at 813"},{"src":"argument","who":"Mr. Sher","text":"And, again, the statistics from the Seventh Circuit are actually ambiguous because, as the local government associations' amici point out, while, in Lu Junhong, the Seventh Circuit said that following our opinion it would be frivolous to assert federal officer removal as a basis for removal in future cases, in fact, there have been future cases in other -- albeit in other circuits, raising exactly the same issue."}]},{"t":"case","label":"Marshall v. Blake","cite":"885 F.3d 1065","y":2018,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/885/1065/","by":{"0":"25"}},{"t":"case","label":"Marx v. General Revenue Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"by":{"0":"19"}},{"t":"case","label":"Meadows v. United Services, Inc.","cite":"963 F.3d 240","y":2020,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/963/240/","by":{"0":"36"}},{"t":"case","label":"Munaf v. Geren","cite":"553 U.S. 674","y":2008,"id":"2007/06-1666","sc":1,"by":{"0":"22"}},{"t":"case","label":"National Farmers Union Insurance Cos. v. Crow Tribe of Indians","cite":"471 U.S. 845","y":1985,"id":"1984/84-320","sc":1,"by":{"0":"39"},"q":[{"src":"brief","b":0,"text":"founded upon federal common law as well as those of a statutory origin.","cite":"471 U.S. 845, 850"}]},{"t":"case","label":"National Weather Service Employees v. Federal Labor Relations Authority","cite":"966 F.3d 875","y":2020,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/966/875/","by":{"0":"25"},"q":[{"src":"brief","b":0,"text":"only the portion of the order that discusses the alleged unfair labor practice.","cite":"966 F.3d 875, 879-880"}]},{"t":"case","label":"Noel v. McCain","cite":"538 F.2d 633","y":1976,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/538/633/","by":{"0":"10, 11","1":"6"}},{"t":"case","label":"Pepper v. United States","cite":"562 U.S. 476","y":2011,"id":"2010/09-6822","sc":1,"by":{"0":"19"}},{"t":"case","label":"Pepperling v. Risley","cite":"739 F.2d 443","y":1984,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/739/443/","by":{"0":"36"}},{"t":"case","label":"Pierce v. Underwood","cite":"487 U.S. 552","y":1988,"id":"1987/86-1512","sc":1,"by":{"0":"34","2":"passim"},"q":[{"src":"brief","b":2,"text":"Quite obviously, reenacting precisely the same language would be a strange way to make a change.","cite":"487 U.S. 552, 567"}]},{"t":"case","label":"PPL Montana LLC v. Montana","cite":"565 U.S. 576","y":2012,"id":"2011/10-218","sc":1,"by":{"0":"39"}},{"t":"case","label":"Quackenbush v. Allstate Insurance Co.","cite":"517 U.S. 706","y":1996,"id":"1995/95-244","sc":1,"by":{"0":"17","1":"12, 16, 21"},"q":[{"src":"brief","b":1,"text":"[f ]ederal courts have a virtually unflagging obligation to exercise the jurisdiction given,","cite":"517 U.S. 706, 716"}]},{"t":"case","label":"Raymond B. Yates, M.D., P.C., Profit Sharing Plan v. Hendon","cite":"541 U.S. 1","y":2004,"id":"2003/02-458","sc":1,"by":{"0":"19"}},{"t":"case","label":"Rhode Island v. Shell Oil Products Co.","cite":"2020 WL 6336000","y":2020,"court":"1st Cir. Oct. 29","by":{"0":"7"}},{"t":"case","label":"Shapiro v. McManus","cite":"136 S. Ct. 450","y":2015,"id":"2015/14-990","sc":1,"by":{"0":"36","1":"19, 30"},"q":[{"src":"argument","who":"Mr. Lucas","text":"Hood-type situation and I think it would be analogous to the three-judge district court context, where this Court in recent cases, such as Shapiro, has reaffirmed that if a party seeks to get a three-judge court jurisdiction and then this Court's direct review under 1253 and the constitutional claim is an insubstantial one, then it can -- the entire case being --"}]},{"t":"case","label":"Smith v. Vulcan Iron Works","cite":"165 U.S. 518","y":1897,"id":"scdb/1896-273","sc":1,"by":{"0":"22","1":"18"}},{"t":"case","label":"Sprint Communications, Inc. v. Jacobs","cite":"571 U.S. 69","y":2013,"id":"2013/12-815","sc":1,"by":{"0":"17"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"courts are obliged to decide cases within the scope of federal jurisdiction","cite":"571 U. S. 69, 72"}]},{"t":"case","label":"Supreme Court of Virginia v. Consumers Union of United States, Inc.","cite":"446 U.S. 719","y":1980,"id":"1979/79-198","sc":1,"by":{"0":"23"}},{"t":"case","label":"Taniguchi v. Kan Pacific Saipan, Ltd.","cite":"566 U.S. 560","y":2012,"id":"2011/10-1472","sc":1,"by":{"0":"16"},"q":[{"src":"brief","b":0,"text":"give[s] the term its ordinary meaning.","cite":"566 U.S. 560, 566"}]},{"t":"case","label":"Teamsters v. Peña","cite":"17 F.3d 1478","y":1994,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/17/1478/","by":{"0":"19"}},{"t":"case","label":"Texas Industries, Inc. v. Radcliff Materials, Inc.","cite":"451 U.S. 630","y":1981,"id":"1980/79-1144","sc":1,"by":{"0":"38","3":"20"},"q":[{"src":"brief","b":0,"text":"the interstate or international nature of the controversy makes it inappropriate for state law to control.","cite":"451 U.S. 630, 640-641"},{"src":"brief","b":3,"text":"our federal system does not permit the controversy to be resolved under state law","cite":"451 U.S. 630, 641"}]},{"t":"case","label":"Thermtron Products, Inc. v. Hermansdorfer","cite":"423 U.S. 336","y":1976,"id":"1975/74-206","sc":1,"by":{"0":"5, 26, 30","1":"4, 16","2":"10, 16","3":"6"},"q":[{"src":"brief","b":0,"text":"prevent delay in the trial of remanded cases by protracted litigation of jurisdictional issues.","cite":"423 U.S. at 351"},{"src":"brief","b":1,"text":"apparently inadvertently omitted from the 1948 revision of the Judicial Code.","cite":"423 U.S. 336, 360"},{"src":"brief","b":2,"text":"whether erroneous or not and whether review is sought by appeal or by extraordinary writ.","cite":"423 U.S. 336, 343"}]},{"t":"case","label":"United States v. Connolly","cite":"716 F.2d 882","y":1983,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/716/882/","by":{"0":"25"}},{"t":"case","label":"United States v. Seatrain Lines","cite":"329 U.S. 424","y":1947,"id":"scdb/1946-029","sc":1,"by":{"0":"17"}},{"t":"case","label":"United States v. Standard Oil Co.","cite":"332 U.S. 301","y":1947,"id":"scdb/1946-139","sc":1,"by":{"0":"38, 45","1":"26, 27","3":"19, 20"},"q":[{"src":"brief","b":0,"text":"unimpaired for dealing independently, wherever necessary or appropriate, with essentially federal matters, even though Congress has not acted affirmatively about the specific question.","cite":"332 U.S. 301, 307"},{"src":"brief","b":1,"text":"Congress has not acted affirmatively about the specific question.","cite":"332 U.S. 301, 307"}]},{"t":"case","label":"Watson v. Philip Morris Cos.","cite":"551 U.S. 142","y":2007,"id":"2006/05-1284","sc":1,"by":{"0":"26, 27, 28, 29","1":"21"},"q":[{"src":"brief","b":0,"text":"the [g]overnment itself would have had to perform","cite":"551 U.S. at 154"}]},{"t":"case","label":"White v. Regester","cite":"412 U.S. 755","y":1973,"id":"1972/72-147","sc":1,"by":{"0":"23"}},{"t":"case","label":"Yamaha Motor Corp., U.S.A. v. Calhoun","cite":"516 U.S. 199","y":1996,"id":"1995/94-1387","sc":1,"by":{"0":"passim","1":"1, 7, 8, 17, 19, 20","3":"11"},"q":[{"src":"brief","b":0,"text":"an immediate appeal from the order may materially advance the ultimate termination of the litigation.","cite":"516 U.S. at 203"},{"src":"brief","b":1,"text":"address any issue fairly included within the certified order.","cite":"516 U.S. 199, 205"},{"src":"brief","b":1,"text":"the appellate court may address any issue fairly included within","cite":"516 U.S. 199, 205"},{"src":"argument","who":"Mr. Shanmugam","text":"It is certainly true that several circuits had adopted Respondent's interpretation, but they did so with conclusory reasoning, and most of them predated this Court's decision in Yamaha, where the Court construed a statute using materially identical language in the opposite direction."},{"src":"argument","who":"Justice Sotomayor","text":"-- Yamaha had already been decided, counsel, and despite that, those circuit courts were ruling against you."},{"src":"argument","who":"Mr. Shanmugam","text":"Well, I think most of the circuit decisions that Respondent invokes predated Yamaha. There were a few that postdated it. But our submission is simply that Yamaha ought to be taken into account."}]},{"t":"law","label":"Pub. L. No. 88-352","url":"https://www.govinfo.gov/link/statute/78/266","by":{"0":"6, 27","1":"5"}},{"t":"usc","label":"42 U.S.C. § 7401-7671q","url":"https://www.law.cornell.edu/uscode/text/42/7401-7671q","by":{"0":"28","3":"19, 20"}},{"t":"law","label":"Pub. L. No. 94-258","url":"https://www.govinfo.gov/link/statute/90/303","by":{"0":"8"}},{"t":"law","label":"Pub. L. No. 112-51","url":"https://www.govinfo.gov/link/plaw/112/public/51","by":{"0":"6, 27, 35","1":"5","3":"9"}},{"t":"usc","label":"5 U.S.C. § 7123","url":"https://www.law.cornell.edu/uscode/text/5/7123","subs":["(a)"],"by":{"0":"25"}},{"t":"usc","label":"11 U.S.C. § 547","url":"https://www.law.cornell.edu/uscode/text/11/547","subs":["(b)"],"by":{"0":"19"}},{"t":"usc","label":"11 U.S.C. § 550","url":"https://www.law.cornell.edu/uscode/text/11/550","by":{"0":"19"}},{"t":"usc","label":"18 U.S.C. § 3553","url":"https://www.law.cornell.edu/uscode/text/18/3553","subs":["(f)"],"by":{"0":"19"}},{"t":"usc","label":"28 U.S.C. § 158","url":"https://www.law.cornell.edu/uscode/text/28/158","subs":["(a)","(d)(2)"],"by":{"0":"24, 24"},"q":[{"src":"brief","b":0,"text":"materially advance the progress of the case.","cite":"28 U.S.C. 158(a)"}]},{"t":"usc","label":"28 U.S.C. § 1253","url":"https://www.law.cornell.edu/uscode/text/28/1253","by":{"0":"23","1":"18, 19, 20","2":"21, 22"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)","(2)"],"by":{"0":"1, 18","1":"14"},"q":[{"src":"brief","b":1,"text":"require the entire record to be sent up for decision of the entire matter in controversy,","cite":"28 U.S.C. 1254(2)"}]},{"t":"usc","label":"28 U.S.C. § 1291","url":"https://www.law.cornell.edu/uscode/text/28/1291","stext":{"head":"§1291. Final decisions of district courts","paras":[[0,"The courts of appeals (other than the United States Court of Appeals for the Federal Circuit) shall have jurisdiction of appeals from all final decisions of the district courts of the United States, the United States District Court for the District of the Canal Zone, the District Court of Guam, and the District Court of the Virgin Islands, except where a direct review may be had in the Supreme Court. The jurisdiction of the United States Court of Appeals for the Federal Circuit shall be limited to the jurisdiction described in sections 1292(c) and (d) and 1295 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1291?type=usc&year=mostrecent&link-type=html"},"by":{"0":"32","1":"16","2":"5, 12, 13, 14","3":"3, 13"},"q":[{"src":"argument","who":"Mr. Sher","text":"And both the structure of the sentence, that is, the tethering to 1442 and 1443, and this Court's treatment of similar language in other statutes, like 1257, the Criminal Appeals Act, and Section 1291, review -- review of single orders is limited to certain issues within those orders, even though the language of the statute itself doesn't distinguish among those issues."},{"src":"argument","who":"Mr. Sher","text":"Well, I think you start with this Court's interpretations of Section 1291 in which the Court has said that, despite virtually identical language about what is appealable from the district courts, that -- that only certain issues within an order are appealable and -- or reviewable and others are not, and -- and the other two statutes that -- that we discuss at length in our brief."},{"src":"argument","who":"Mr. Shanmugam","text":"Of course, under Section 1291, plenary review is the default, not the exception, in our appellate system, but there's no reason to believe that there are going to be a lot of these cases."}]},{"t":"usc","label":"28 U.S.C. § 1292","url":"https://www.law.cornell.edu/uscode/text/28/1292","subs":["(a)(1)","(b)","(d)(2)"],"stext":{"head":"§1292. Interlocutory decisions","paras":[[0,"(a) Except as provided in subsections (c) and (d) of this section, the courts of appeals shall have jurisdiction of appeals from:"],[1,"(1) Interlocutory orders of the district courts of the United States, the United States District Court for the District of the Canal Zone, the District Court of Guam, and the District Court of the Virgin Islands, or of the judges thereof, granting, continuing, modifying, refusing or dissolving injunctions, or refusing to dissolve or modify injunctions, except where a direct review may be had in the Supreme Court;"],[1,"(2) Interlocutory orders appointing receivers, or refusing orders to wind up receiverships or to take steps to accomplish the purposes thereof, such as directing sales or other disposals of property;"],[1,"(3) Interlocutory decrees of such district courts or the judges thereof determining the rights and liabilities of the parties to admiralty cases in which appeals from final decrees are allowed."],[0,"(b) When a district judge, in making in a civil action an order not otherwise appealable under this section, shall be of the opinion that such order involves a controlling question of law as to which there is substantial ground for difference of opinion and that an immediate appeal from the order may materially advance the ultimate termination of the litigation, he shall so state in writing in such order. The Court of Appeals which would have jurisdiction of an appeal of such action may thereupon, in its discretion, permit an appeal to be taken from such order, if application is made to it within ten days after the entry of the order: Provided, however, That application for an appeal hereunder shall not stay proceedings in the district court unless the district judge or the Court of Appeals or a judge thereof shall so order."],[0,"(c) The United States Court of Appeals for the Federal Circuit shall have exclusive jurisdiction—"],[1,"(1) of an appeal from an interlocutory order or decree described in subsection (a) or (b) of this section in any case over which the court would have jurisdiction of an appeal under section 1295 of this title; and"],[1,"(2) of an appeal from a judgment in a civil action for patent infringement which would otherwise be appealable to the United States Court of Appeals for the Federal Circuit and is final except for an accounting."],[0,"(d)(1) When the chief judge of the Court of International Trade issues an order under the provisions of section 256(b) of this title, or when any judge of the Court of International Trade, in issuing any other interlocutory order, includes in the order a statement that a controlling question of law is involved with respect to which there is a substantial ground for difference of opinion and that an immediate appeal from that order may materially advance the ultimate termination of the litigation, the United States Court of Appeals for the Federal Circuit may, in its discretion, permit an appeal to be taken from such order, if application is made to that Court within ten days after the entry of such order."],[0,"(2) When the chief judge of the United States Court of Federal Claims issues an order under section 798(b) of this title, or when any judge of the United States Court of Federal Claims, in issuing an interlocutory order, includes in the order a statement that a controlling question of law is involved with respect to which there is a substantial ground for difference of opinion and that an immediate appeal from that order may materially advance the ultimate termination of the litigation, the United States Court of Appeals for the Federal Circuit may, in its discretion, permit an appeal to be taken from such order, if application is made to that Court within ten days after the entry of such order."],[0,"(3) Neither the application for nor the granting of an appeal under this subsection shall stay proceedings in the Court of International Trade or in the Court of Federal Claims, as the case may be, unless a stay is ordered by a judge of the Court of International Trade or of the Court of Federal Claims or by the United States Court of Appeals for the Federal Circuit or a judge of that court."],[0,"(4)(A) The United States Court of Appeals for the Federal Circuit shall have exclusive jurisdiction of an appeal from an interlocutory order of a district court of the United States, the District Court of Guam, the District Court of the Virgin Islands, or the District Court for the Northern Mariana Islands, granting or denying, in whole or in part, a motion to transfer an action to the United States Court of Federal Claims under section 1631 of this title."],[0,"(B) When a motion to transfer an action to the Court of Federal Claims is filed in a district court, no further proceedings shall be taken in the district court until 60 days after the court has ruled upon the motion. If an appeal is taken from the district court's grant or denial of the motion, proceedings shall be further stayed until the appeal has been decided by the Court of Appeals for the Federal Circuit. The stay of proceedings in the district court shall not bar the granting of preliminary or injunctive relief, where appropriate and where expedition is reasonably necessary. However, during the period in which proceedings are stayed as provided in this subparagraph, no transfer to the Court of Federal Claims pursuant to the motion shall be carried out."],[0,"(e) The Supreme Court may prescribe rules, in accordance with section 2072 of this title, to provide for an appeal of an interlocutory decision to the courts of appeals that is not otherwise provided for under subsection (a), (b), (c), or (d)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1292?type=usc&year=mostrecent&link-type=html"},"by":{"0":"22, 10, 21, 32, 25","1":"18, passim","2":"11, 21, 22","3":"11"},"q":[{"src":"brief","b":0,"text":"such order involves a controlling question of law as to which there is substantial ground for difference of opinion and that an immediate appeal from the order may materially advance the ultimate termination of the litigation.","cite":"28 U.S.C. 1292(b)"},{"src":"brief","b":2,"text":"involves a controlling question of law as to which there is a substantial ground for difference of opinion.","cite":"28 U.S.C. 1292(b)"}]},{"t":"usc","label":"28 U.S.C. § 1295","url":"https://www.law.cornell.edu/uscode/text/28/1295","subs":["(a)(7)"],"by":{"0":"18"}},{"t":"usc","label":"28 U.S.C. § 1331","url":"https://www.law.cornell.edu/uscode/text/28/1331","by":{"0":"39, 45","1":"2","2":"39, 41, 44, 46"},"q":[{"src":"brief","b":1,"text":"arising under the Constitution, laws, or treaties of the United States,","cite":"28 U.S.C. 1331"}]},{"t":"usc","label":"28 U.S.C. § 1441","url":"https://www.law.cornell.edu/uscode/text/28/1441","subs":["(a)","(b)(2)"],"by":{"0":"4, 39, 45, 20","1":"2, 26, 15","2":"32, 33, 39"},"q":[{"src":"brief","b":1,"text":"any civil action brought in a State court of which the district courts of the United States have original jurisdiction,","cite":"28 U.S.C. 1441(a)"},{"src":"brief","b":1,"text":"may not be removed if any of the parties in interest properly joined and served as defendants is a citizen of the State in which such action is brought.","cite":"28 U.S.C. 1441(b)(2)"}]},{"t":"usc","label":"28 U.S.C. § 1442","url":"https://www.law.cornell.edu/uscode/text/28/1442","subs":["(a)","(a)(1)","(a)(2)"],"stext":{"head":"§1442. Federal officers or agencies sued or prosecuted","paras":[[0,"(a) A civil action or criminal prosecution that is commenced in a State court and that is against or directed to any of the following may be removed by them to the district court of the United States for the district and division embracing the place wherein it is pending:"],[1,"(1) The United States or any agency thereof or any officer (or any person acting under that officer) of the United States or of any agency thereof, in an official or individual capacity, for or relating to any act under color of such office or on account of any right, title or authority claimed under any Act of Congress for the apprehension or punishment of criminals or the collection of the revenue."],[1,"(2) A property holder whose title is derived from any such officer, where such action or prosecution affects the validity of any law of the United States."],[1,"(3) Any officer of the courts of the United States, for or relating to any act under color of office or in the performance of his duties;"],[1,"(4) Any officer of either House of Congress, for or relating to any act in the discharge of his official duty under an order of such House."],[0,"(b) A personal action commenced in any State court by an alien against any citizen of a State who is, or at the time the alleged action accrued was, a civil officer of the United States and is a nonresident of such State, wherein jurisdiction is obtained by the State court by personal service of process, may be removed by the defendant to the district court of the United States for the district and division in which the defendant was served with process."],[0,"(c) Solely for purposes of determining the propriety of removal under subsection (a), a law enforcement officer, who is the defendant in a criminal prosecution, shall be deemed to have been acting under the color of his office if the officer—"],[1,"(1) protected an individual in the presence of the officer from a crime of violence;"],[1,"(2) provided immediate assistance to an individual who suffered, or who was threatened with, bodily harm; or"],[1,"(3) prevented the escape of any individual who the officer reasonably believed to have committed, or was about to commit, in the presence of the officer, a crime of violence that resulted in, or was likely to result in, death or serious bodily injury."],[0,"(d) In this section, the following definitions apply:"],[1,"(1) The terms \"civil action\" and \"criminal prosecution\" include any proceeding (whether or not ancillary to another proceeding) to the extent that in such proceeding a judicial order, including a subpoena for testimony or documents, is sought or issued. If removal is sought for a proceeding described in the previous sentence, and there is no other basis for removal, only that proceeding may be removed to the district court."],[1,"(2) The term \"crime of violence\" has the meaning given that term in section 16 of title 18."],[1,"(3) The term \"law enforcement officer\" means any employee described in subparagraph (A), (B), or (C) of section 8401(17) of title 5 and any special agent in the Diplomatic Security Service of the Department of State."],[1,"(4) The term \"serious bodily injury\" has the meaning given that term in section 1365 of title 18."],[1,"(5) The term \"State\" includes the District of Columbia, United States territories and insular possessions, and Indian country (as defined in section 1151 of title 18)."],[1,"(6) The term \"State court\" includes the Superior Court of the District of Columbia, a court of a United States territory or insular possession, and a tribal court."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1442?type=usc&year=mostrecent&link-type=html"},"by":{"0":"passim","1":"1, 3, 24, 25, 29, 3, 3, 3","2":"passim","3":"passim"},"q":[{"src":"brief","b":1,"text":"for or relating to any act under color of such office or on account of any right, title or authority claimed under any Act of Congress for the apprehension or punishment of criminals or the collection of the revenue.","cite":"28 U.S.C. 1442(a)(1)"},{"src":"brief","b":1,"text":"any act under color of such office,","cite":"28 U.S.C. 1442(a)(1)"},{"src":"argument","who":"Mr. Sher","text":"Chief Justice, and may it please the Court: According to Petitioners, merely referring to Section 1442 in a removal notice guarantees a defendant an appeal as of right of every ground rejected by the district court, even if the 1442 ground is meritless and even if the defendant drops it on appeal."},{"src":"argument","who":"Mr. Sher","text":"And, there, we see that an order is reviewable but only if it is an order that -- in which the removal was pursuant to Section 1442 or 1443."},{"src":"argument","who":"Mr. Sher","text":"So \"pursuant to Section 1442 or 1443\" must mean something other than simply that the notice of removal referenced them, and this is why that language acts both as a tether as a matter of -- of -- of commonsense interpretation of the statute, focusing the court of appeals' attention on those issues and those issues alone, and as a substantive bar because \"pursuant to,\" as this Court has interpreted it in other contexts and as the Constitution uses the -- the phrase \"in pursuance to\" for legislation, means not just procedural compliance but substantive compliance."}]},{"t":"usc","label":"28 U.S.C. § 1443","url":"https://www.law.cornell.edu/uscode/text/28/1443","subs":["(1)","(2)"],"stext":{"head":"§1443. Civil rights cases","paras":[[0,"Any of the following civil actions or criminal prosecutions, commenced in a State court may be removed by the defendant to the district court of the United States for the district and division embracing the place wherein it is pending:"],[1,"(1) Against any person who is denied or cannot enforce in the courts of such State a right under any law providing for the equal civil rights of citizens of the United States, or of all persons within the jurisdiction thereof;"],[1,"(2) For any act under color of authority derived from any law providing for equal rights, or for refusing to do any act on the ground that it would be inconsistent with such law."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1443?type=usc&year=mostrecent&link-type=html"},"by":{"0":"passim, 27, 27","1":"1, 2, 24, 25, 29, 2, 3","2":"passim","3":"passim"},"q":[{"src":"brief","b":1,"text":"providing for the equal civil rights of citizens of the United States, or of all persons within the jurisdiction thereof,","cite":"28 U.S.C. 1443(1)"},{"src":"brief","b":1,"text":"[f ]or any act under color of authority derived from any law providing for equal rights,","cite":"28 U.S.C. 1443(2)"}]},{"t":"usc","label":"28 U.S.C. § 1446","url":"https://www.law.cornell.edu/uscode/text/28/1446","subs":["(a)","(d)"],"stext":{"head":"§1446. Procedure for removal of civil actions","paras":[[0,"(a) Generally.—A defendant or defendants desiring to remove any civil action from a State court shall file in the district court of the United States for the district and division within which such action is pending a notice of removal signed pursuant to Rule 11 of the Federal Rules of Civil Procedure and containing a short and plain statement of the grounds for removal, together with a copy of all process, pleadings, and orders served upon such defendant or defendants in such action."],[0,"(b) Requirements; Generally.—(1) The notice of removal of a civil action or proceeding shall be filed within 30 days after the receipt by the defendant, through service or otherwise, of a copy of the initial pleading setting forth the claim for relief upon which such action or proceeding is based, or within 30 days after the service of summons upon the defendant if such initial pleading has then been filed in court and is not required to be served on the defendant, whichever period is shorter."],[0,"(2)(A) When a civil action is removed solely under section 1441(a), all defendants who have been properly joined and served must join in or consent to the removal of the action."],[0,"(B) Each defendant shall have 30 days after receipt by or service on that defendant of the initial pleading or summons described in paragraph (1) to file the notice of removal."],[0,"(C) If defendants are served at different times, and a later-served defendant files a notice of removal, any earlier-served defendant may consent to the removal even though that earlier-served defendant did not previously initiate or consent to removal."],[0,"(3) Except as provided in subsection (c), if the case stated by the initial pleading is not removable, a notice of removal may be filed within thirty days after receipt by the defendant, through service or otherwise, of a copy of an amended pleading, motion, order or other paper from which it may first be ascertained that the case is one which is or has become removable."],[0,"(c) Requirements; Removal Based on Diversity of Citizenship.—(1) A case may not be removed under subsection (b)(3) on the basis of jurisdiction conferred by section 1332 more than 1 year after commencement of the action, unless the district court finds that the plaintiff has acted in bad faith in order to prevent a defendant from removing the action."],[0,"(2) If removal of a civil action is sought on the basis of the jurisdiction conferred by section 1332(a), the sum demanded in good faith in the initial pleading shall be deemed to be the amount in controversy, except that—"],[1,"(A) the notice of removal may assert the amount in controversy if the initial pleading seeks—"],[2,"(i) nonmonetary relief; or"],[2,"(ii) a money judgment, but the State practice either does not permit demand for a specific sum or permits recovery of damages in excess of the amount demanded; and"],[1,"(B) removal of the action is proper on the basis of an amount in controversy asserted under subparagraph (A) if the district court finds, by the preponderance of the evidence, that the amount in controversy exceeds the amount specified in section 1332(a)."],[0,"(3)(A) If the case stated by the initial pleading is not removable solely because the amount in controversy does not exceed the amount specified in section 1332(a), information relating to the amount in controversy in the record of the State proceeding, or in responses to discovery, shall be treated as an \"other paper\" under subsection (b)(3)."],[0,"(B) If the notice of removal is filed more than 1 year after commencement of the action and the district court finds that the plaintiff deliberately failed to disclose the actual amount in controversy to prevent removal, that finding shall be deemed bad faith under paragraph (1)."],[0,"(d) Notice to Adverse Parties and State Court.—Promptly after the filing of such notice of removal of a civil action the defendant or defendants shall give written notice thereof to all adverse parties and shall file a copy of the notice with the clerk of such State court, which shall effect the removal and the State court shall proceed no further unless and until the case is remanded."],[0,"(e) Counterclaim in 337 Proceeding.—With respect to any counterclaim removed to a district court pursuant to section 337(c) of the Tariff Act of 1930, the district court shall resolve such counterclaim in the same manner as an original complaint under the Federal Rules of Civil Procedure, except that the payment of a filing fee shall not be required in such cases and the counterclaim shall relate back to the date of the original complaint in the proceeding before the International Trade Commission under section 337 of that Act."],[0,"(g) 1 Where the civil action or criminal prosecution that is removable under section 1442(a) is a proceeding in which a judicial order for testimony or documents is sought or issued or sought to be enforced, the 30-day requirement of subsection (b) of this section and paragraph (1) of section 1455(b) is satisfied if the person or entity desiring to remove the proceeding files the notice of removal not later than 30 days after receiving, through service, notice of any such proceeding."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1446?type=usc&year=mostrecent&link-type=html"},"by":{"0":"4","1":"2, 2","3":"7, 7"},"q":[{"src":"brief","b":1,"text":"containing a short and plain statement of the grounds for removal.","cite":"28 U.S.C. 1446(a)"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"further unless and until the case is remanded.","cite":"28 U. S. C. § 1446(d)"}]},{"t":"usc","label":"28 U.S.C. § 1447","url":"https://www.law.cornell.edu/uscode/text/28/1447","subs":["(c)","(d)"],"stext":{"head":"§1447. Procedure after removal generally","paras":[[0,"(a) In any case removed from a State court, the district court may issue all necessary orders and process to bring before it all proper parties whether served by process issued by the State court or otherwise."],[0,"(b) It may require the removing party to file with its clerk copies of all records and proceedings in such State court or may cause the same to be brought before it by writ of certiorari issued to such State court."],[0,"(c) A motion to remand the case on the basis of any defect other than lack of subject matter jurisdiction must be made within 30 days after the filing of the notice of removal under section 1446(a). If at any time before final judgment it appears that the district court lacks subject matter jurisdiction, the case shall be remanded. An order remanding the case may require payment of just costs and any actual expenses, including attorney fees, incurred as a result of the removal. A certified copy of the order of remand shall be mailed by the clerk to the clerk of the State court. The State court may thereupon proceed with such case."],[0,"(d) An order remanding a case to the State court from which it was removed is not reviewable on appeal or otherwise, except that an order remanding a case to the State court from which it was removed pursuant to section 1442 or 1443 of this title shall be reviewable by appeal or otherwise."],[0,"(e) If after removal the plaintiff seeks to join additional defendants whose joinder would destroy subject matter jurisdiction, the court may deny joinder, or permit joinder and remand the action to the State court."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1447?type=usc&year=mostrecent&link-type=html"},"by":{"0":"4, 35, passim","1":"4, 30, 4, 11, passim","2":"passim","3":"7, 5, 6, 16, passim"},"q":[{"src":"brief","b":0,"text":"just costs and any actual expenses, including attorney fees, incurred as a result of the removal.","cite":"28 U.S.C. 1447(c)"},{"src":"brief","b":1,"text":"[a]n order remanding a case to the State court from which it was removed is not reviewable on appeal or otherwise.","cite":"28 U.S.C. 1447(d)"},{"src":"brief","b":1,"text":"was removed pursuant to section 1442","cite":"28 U.S.C. 1447(d)"},{"src":"brief","b":2,"text":"case[s] . . . removed pursuant to section 1442 or 1443.","cite":"28 U.S.C. 1447(d)"},{"src":"brief","b":2,"text":"remanding a case . . . removed pursuant to section 1442 or 1443.","cite":"28 U.S.C. 1447(d)"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"[a]n order remanding a case to the State court from which it was removed is not reviewable on appeal or otherwise, except that an order remanding a case to the State court from which it was removed pursuant to section 1442 or 1443 of this title shall be reviewable by appeal or otherwise.","cite":"28 U. S. C. § 1447(d)"},{"src":"argument","who":"Mr. Sher","text":"And let me -- let me point to one other structural thing in Section 1447 itself that supports this analysis. Section 1447(c) says that an order remanding the case may require payment of just costs and expenses incurred as a result of the removal."}]},{"t":"usc","label":"28 U.S.C. § 1453","url":"https://www.law.cornell.edu/uscode/text/28/1453","subs":["(c)(1)","(c)","(d)(3)"],"by":{"0":"25","1":"31, 4","2":"28"},"q":[{"src":"brief","b":0,"text":"order of a district court granting or denying a motion to remand a class action.","cite":"28 U.S.C. 1453(c)(1)"},{"src":"brief","b":1,"text":"may accept an appeal from an order of a district court granting or denying a motion to remand a class action to the State court from which it was removed.","cite":"28 U.S.C. 1453(c)(1)"}]},{"t":"usc","label":"28 U.S.C. § 2342","url":"https://www.law.cornell.edu/uscode/text/28/2342","subs":["(5)"],"by":{"0":"20"}},{"t":"usc","label":"38 U.S.C. § 7292","url":"https://www.law.cornell.edu/uscode/text/38/7292","subs":["(b)(1)"],"by":{"0":"18","1":"14"}},{"t":"usc","label":"42 U.S.C. § 8514","url":"https://www.law.cornell.edu/uscode/text/42/8514","subs":["(a)(2)"],"by":{"0":"18"}},{"t":"usc","label":"50 U.S.C. § 1803","url":"https://www.law.cornell.edu/uscode/text/50/1803","subs":["(j)"],"by":{"0":"18"}},{"t":"usc","label":"52 U.S.C. § 30110","url":"https://www.law.cornell.edu/uscode/text/52/30110","by":{"0":"18"}},{"t":"rule","label":"Fed. R. Civ. P. 11","url":"https://www.law.cornell.edu/rules/frcp/rule_11","subs":["(b)(1)","(b)(2)","(b)"],"by":{"0":"35, 35","1":"30"}},{"t":"case","label":"Abbott v. Perez","cite":"138 S. Ct. 2305","y":2018,"id":"2017/17-586","sc":1,"by":{"1":"25"}},{"t":"case","label":"Bersch v. Drexel Firestone, Inc.","cite":"519 F.2d 974","y":1975,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/519/974/","by":{"1":"14"}},{"t":"case","label":"Brown v. Gardner","cite":"513 U.S. 115","y":1994,"id":"1994/93-1128","sc":1,"by":{"1":"13"},"q":[{"src":"brief","b":1,"text":"at its most vigorous when a term is repeated within a given sentence.","cite":"513 U.S. 115, 118"}]},{"t":"case","label":"Carnegie-Mellon Univ. v. Cohill","cite":"484 U.S. 343","y":1988,"id":"1987/86-1021","sc":1,"by":{"1":"12"},"q":[{"src":"brief","b":1,"text":"eliminate[] the case from its docket, whether by a remand or by a dismissal,","cite":"484 U.S. 343, 356"}]},{"t":"case","label":"Chevron U.S.A. Inc. v. Natural Res. Def. Council, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"by":{"1":"19"},"q":[{"src":"brief","b":1,"text":"legal error resulted in an erroneous judgment.","cite":"467 U.S. 837, 842"}]},{"t":"case","label":"City of Oakland v. BP PLC","cite":"969 F.3d 895","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/969/895/","by":{"1":"21","3":"17"}},{"t":"case","label":"Dothard v. Rawlinson","cite":"433 U.S. 321","y":1977,"id":"1976/76-422","sc":1,"by":{"1":"19"}},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"138 S. Ct. 1134","y":2018,"id":"2017/16-1362","sc":1,"by":{"1":"16"},"q":[{"src":"brief","b":1,"text":"have no license to give the exemption anything but a fair reading.","cite":"138 S. Ct. 1134, 1142"}]},{"t":"case","label":"Jefferson Cnty. v. Acker","cite":"527 U.S. 423","y":1999,"id":"1998/98-10","sc":1,"by":{"1":"3"},"q":[{"src":"brief","b":1,"text":"a nexus, a causal connection between the charged conduct and asserted official authority,","cite":"527 U.S. 423, 431"}]},{"t":"case","label":"Kircher v. Putnam Funds Trust","cite":"547 U.S. 633","y":2006,"id":"2005/05-409","sc":1,"by":{"1":"14, 23"}},{"t":"case","label":"Mesa v. California","cite":"489 U.S. 121","y":1989,"id":"1988/87-1206","sc":1,"by":{"1":"3"}},{"t":"case","label":"Milner v. Department of the Navy","cite":"562 U.S. 562","y":2011,"id":"2010/09-1163","sc":1,"by":{"1":"22"},"q":[{"src":"brief","b":1,"text":"no warrant to ignore clear statutory language on the ground that other courts have done so,","cite":"562 U.S. 562, 576"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"warrant to ignore clear statutory language on the ground that other courts have done so.","cite":"562 U. S. 562, 576"},{"src":"argument","who":"Mr. Lucas","text":"I -- I think so, Your Honor, and that's at least how I understand cases such as Milner versus Department of Navy and the like. But even if you disagree with me, Justice Kavanaugh, I still think, in this context, it's hard to say that Congress thought this question was settled in 2011, which I think everybody agrees is the sort of touchstone of the ratification analysis, when you have on the one side, yes, a number of circuit cases, but they're poorly reasoned ones, and on the other side, you do have this Court's precedents in other areas and the leading treatise."}]},{"t":"case","label":"Osborn v. Haley","cite":"549 U.S. 225","y":2007,"id":"2006/05-593","sc":1,"by":{"1":"1"}},{"t":"case","label":"Powerex Corp. v. Reliant Energy Servs., Inc.","cite":"551 U.S. 224","y":2007,"id":"2006/05-85","sc":1,"by":{"1":"1, 5, 14, 16, 23, 31"},"q":[{"src":"brief","b":1,"text":"reflects Congress’s longstanding ‘policy of not permitting interruption of the litigation of the merits of a removed case by prolonged litigation of questions of jurisdiction.’","cite":"551 U.S. at 238"},{"src":"brief","b":1,"text":"As far as the Third Branch is concerned, what the text of § 1447(d) indisputably does prevails over what it ought to have done.","cite":"551 U.S. at 237"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"refects Congress's longstanding policy of not permitting interruption of the litigation of the merits of a removed case by prolonged litigation of questions of jurisdiction of the district court to which the cause is removed.","cite":"551 U. S. 224, 238"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"Congress's longstanding policy of not permitting interruption of the litigation of the merits of a removed case","cite":"551 U. S., at 238"}]},{"t":"case","label":"Rivet v. Regions Bank","cite":"522 U.S. 470","y":1998,"id":"1997/96-1971","sc":1,"by":{"1":"28","2":"4, 11","3":"21"},"q":[{"src":"brief","b":1,"text":"may uphold removal even though no federal question appears on the face of the plaintiff ’s complaint.","cite":"522 U.S. 470, 475"},{"src":"brief","b":2,"text":"‘well-pleaded complaint rule[,]’ which provides that federal jurisdiction exists only when a federal question is presented on the face of the plaintiff’s properly pleaded complaint.","cite":"522 U.S. 470, 475"},{"src":"brief","b":3,"text":"federal law completely preempts a plaintiff’s state-law claim,","cite":"522 U.S. 470, 475"}]},{"t":"case","label":"Sandifer v. United States Steel Corp.","cite":"571 U.S. 220","y":2014,"id":"2013/12-417","sc":1,"by":{"1":"11"},"q":[{"src":"brief","b":1,"text":"be interpreted as taking [its] ordinary, contemporary, common meaning,","cite":"571 U.S. 220, 227"}]},{"t":"case","label":"Siler v. Louisville & Nashville R.R.","cite":"213 U.S. 175","y":1909,"id":"scdb/1908-120","sc":1,"by":{"1":"20"}},{"t":"case","label":"United States v. Stanley","cite":"483 U.S. 669","y":1987,"id":"1986/86-393","sc":1,"by":{"1":"17"}},{"t":"case","label":"Vaden v. Discover Bank","cite":"556 U.S. 49","y":2009,"id":"2008/07-773","sc":1,"by":{"1":"28"}},{"t":"case","label":"Winter v. Natural Res. Def. Council, Inc.","cite":"555 U.S. 7","y":2008,"id":"2008/07-1239","sc":1,"by":{"1":"18"}},{"t":"law","label":"Pub. L. No. 94-381","url":"https://www.govinfo.gov/link/statute/90/1119","by":{"1":"18"}},{"t":"law","label":"Pub. L. No. 109-2","url":"https://www.govinfo.gov/link/plaw/109/public/2","by":{"1":"4"}},{"t":"usc","label":"42 U.S.C. § 7401","url":"https://www.law.cornell.edu/uscode/text/42/7401","by":{"1":"27"}},{"t":"usc","label":"33 U.S.C. § 1251","url":"https://www.law.cornell.edu/uscode/text/33/1251","by":{"1":"27"}},{"t":"usc","label":"28 U.S.C. § 2281","url":"https://www.law.cornell.edu/uscode/text/28/2281","subs":["(1970)"],"by":{"1":"18"},"q":[{"src":"brief","b":1,"text":"upon the ground of the unconstitutionality of such statute,","cite":"28 U.S.C. 2281"}]},{"t":"usc","label":"28 U.S.C. § 2284","url":"https://www.law.cornell.edu/uscode/text/28/2284","subs":["(a)"],"by":{"1":"20, 30"}},{"t":"case","label":"Abney v. United States","cite":"431 U.S. 651","y":1977,"id":"1976/75-6521","sc":1,"by":{"2":"5, 13, 37"},"q":[{"src":"brief","b":2,"text":"collateral to, and separable from the principal issue","cite":"431 U.S. 651, 659, 662–63"},{"src":"argument","who":"Mr. Sher","text":"To the contrary, this Court has -- has frequently disentangled issues and made clear in cases like Swint and Abney and Behrens, all of which Petitioners ignore, that you cannot use an -- an appealable issue as a ticket for multi-issue appeals that are not allowed."},{"src":"argument","who":"Mr. Sher","text":"In Abney, there was a single order, and it was okay for the appellate court to -- to review the order denying the motion to dismiss with respect to double jeopardy but not with respect to the same order denying a challenge to the sufficiency of an indictment."}]},{"t":"case","label":"Alabama v. Conley","cite":"245 F.3d 1292","y":2001,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/245/1292/","by":{"2":"7, 25, 26"}},{"t":"case","label":"All. Envtl., Inc. v. Harrison W. Constr. Corp.","cite":"94 F.3d 644","y":1996,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/94/644/","by":{"2":"9, 21, 37, 44"}},{"t":"case","label":"Bragdon v. Abbott","cite":"524 U.S. 624","y":1998,"id":"1997/97-156","sc":1,"by":{"2":"17, 20"}},{"t":"case","label":"Carroll v. United States","cite":"354 U.S. 394","y":1957,"id":"1956/571","sc":1,"by":{"2":"5, 15"}},{"t":"case","label":"\b City of Waco v. U.S. Fidelity & Guaranty Co.","cite":"293 U.S. 140","y":1934,"id":"scdb/1934-042","sc":1,"by":{"2":"6, 17"}},{"t":"case","label":"Cooter & Gell v. Hartmarx Corp.","cite":"496 U.S. 384","y":1990,"id":"1989/89-275","sc":1,"by":{"2":"8, 21, 44"}},{"t":"case","label":"Davila v. Davis","cite":"137 S. Ct. 2058","y":2017,"id":"2016/16-6219","sc":1,"by":{"2":"17, 34"}},{"t":"case","label":"Forest Grove Sch. Dist. v. T.A.","cite":"557 U.S. 230","y":2009,"id":"2008/08-305","sc":1,"by":{"2":"5, 12","3":"9"}},{"t":"case","label":"Georgia v. Rachel","cite":"384 U.S. 780","y":1966,"id":"1965/147","sc":1,"by":{"2":"3, 15"},"q":[{"src":"brief","b":2,"text":"to give the federal reviewing courts a new opportunity to consider the meaning and scope of [that] removal statute.","cite":"384 U.S. 780, 786–87"}]},{"t":"case","label":"Gordon v. United States","cite":"117 U.S. 697","y":1864,"url":"https://supreme.justia.com/cases/federal/us/117/697/","sc":1,"by":{"2":"10, 37"}},{"t":"case","label":"Hillman v. Maretta","cite":"569 U.S. 483","y":2013,"id":"2012/11-1221","sc":1,"by":{"2":"6, 19"}},{"t":"case","label":"Johnson v. United States","cite":"559 U.S. 133","y":2010,"id":"2009/08-6925","sc":1,"by":{"2":"11, 20, 29"}},{"t":"case","label":"Kirtsaeng v. John Wiley & Sons, Inc.","cite":"568 U.S. 519","y":2013,"id":"2012/11-697","sc":1,"by":{"2":"8, 31, 34"}},{"t":"case","label":"Maracich v. Spears","cite":"570 U.S. 48","y":2013,"id":"2012/12-25","sc":1,"by":{"2":"6, 18, 35, 38","3":"4"},"q":[{"src":"brief","b":2,"text":"[a]n exception to a ‘general statement of policy’ is ‘usually read . . . narrowly in order to preserve the primary operation of the provision,’","cite":"570 U.S. 48, 60"},{"src":"brief","b":2,"text":"ought not operate to the farthest reach of [its] linguistic possibilities if that result would contravene the statutory design.","cite":"570 U.S. at 60"}]},{"t":"case","label":"Massachusetts v. Exxon Mobil Corp.","cite":"462 F. Supp. 3d 31","y":2020,"court":"D. Mass.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/462/31/","by":{"2":"6, 19"}},{"t":"case","label":"\b Metro. Life Ins. Co. v. Taylor","cite":"481 U.S. 58","y":1987,"id":"1986/85-686","sc":1,"by":{"2":"5, 12, 37"},"q":[{"src":"brief","b":2,"text":"reluctan[ce] to find th[e] extraordinary preemptive power","cite":"481 U.S. at 65"}]},{"t":"case","label":"Nat’l Credit Union Admin. v. First Nat’l Bank & Trust Co.","cite":"522 U.S. 479","y":1998,"id":"1997/96-843","sc":1,"by":{"2":"7, 26, 27"}},{"t":"case","label":"Price v. Medicaid Dir.","cite":"838 F.3d 739","y":2016,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/838/739/","by":{"2":"21, 45"}},{"t":"case","label":"Sanchez v. Onuska","cite":"2 F.3d 1160","y":1993,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/2/1160/","by":{"2":"7, 24, 25"}},{"t":"case","label":"Shamrock Oil & Gas Corp. v. Sheets","cite":"313 U.S. 100","y":1941,"id":"scdb/1940-150","sc":1,"by":{"2":"6, 19"}},{"t":"case","label":"Stallworth v. Greater Cleveland Reg’l Transit Auth.","cite":"105 F.3d 252","y":1997,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/105/252/","by":{"2":"11, 37"}},{"t":"case","label":"\b Syngenta Crop Prot., Inc. v. Henson","cite":"537 U.S. 28","y":2002,"id":"2002/01-757","sc":1,"by":{"2":"8, 32, 33"}},{"t":"case","label":"Thornton v. Holloway","cite":"70 F.3d 522","y":1995,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/70/522/","by":{"2":"5, 14"}},{"t":"case","label":"United States v. Brockamp","cite":"519 U.S. 347","y":1997,"id":"1996/95-1225","sc":1,"by":{"2":"5, 14"}},{"t":"case","label":"United States v. Lee","cite":"659 F.3d 619","y":2011,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/659/619/","by":{"2":"7, 28"}},{"t":"case","label":"United States v. Stevenson","cite":"215 U.S. 190","y":1909,"id":"scdb/1909-021","sc":1,"by":{"2":"4, 21"},"q":[{"src":"brief","b":2,"text":"the classes named in the statute giving a right of review in this court.","cite":"215 U.S. 190, 195–96"}]},{"t":"case","label":"Yee v. City of Escondido","cite":"503 U.S. 519","y":1992,"id":"1991/90-1947","sc":1,"by":{"2":"24, 42"},"q":[{"src":"brief","b":2,"text":"are not limited to the precise arguments they made below.","cite":"503 U.S. 519, 534"},{"src":"brief","b":2,"text":"‘[O]nly the questions set forth in the petition, or fairly included therein, will be considered by the Court.’","cite":"503 U.S. at 535"}]},{"t":"case","label":"Zivotofsky ex rel. Zivotofsky v. Clinton","cite":"566 U.S. 189","y":2012,"id":"2011/10-699","sc":1,"by":{"2":"8"}},{"t":"usc","label":"15 U.S.C. § 78bb","url":"https://www.law.cornell.edu/uscode/text/15/78bb","subs":["(f)(1)(A)"],"by":{"2":"18"}},{"t":"usc","label":"28 U.S.C. § 1257","url":"https://www.law.cornell.edu/uscode/text/28/1257","by":{"2":"5, 11, 12, 14","3":"12"},"q":[{"src":"argument","who":"Mr. Sher","text":"And in our brief, we discuss the cases under the Criminal Appeals Act and as well as under Section 1257. You cannot allow a party that has a non-meritorious issue, as defendants -- sorry, as Petitioners have here, to use that issue as a hook to open up issues that this Court and the statute have plainly barred."}]},{"t":"usc","label":"28 U.S.C. § 1332","url":"https://www.law.cornell.edu/uscode/text/28/1332","subs":["(d)(9)(C)"],"by":{"2":"28"}},{"t":"usc","label":"28 U.S.C. § 1354","url":"https://www.law.cornell.edu/uscode/text/28/1354","by":{"2":"7, 30"}},{"t":"usc","label":"29 U.S.C. § 185","url":"https://www.law.cornell.edu/uscode/text/29/185","by":{"2":"29"}},{"t":"usc","label":"44 U.S.C. § 2204","url":"https://www.law.cornell.edu/uscode/text/44/2204","subs":["(e)"],"by":{"2":"7, 30"}},{"t":"const","label":"Article VI","clauses":[["supremacy","Supremacy Clause"],["religious-test","No Religious Test Clause"]],"text":"All Debts contracted and Engagements entered into, before the Adoption of this Constitution, shall be as valid against the United States under this Constitution, as under the Confederation. This Constitution, and the Laws of the United States which shall be made in Pursuance thereof; and all Treaties made, or which shall be made, under the Authority of the United States, shall be the supreme Law of the Land; and the Judges in every State shall be bound thereby, any Thing in the Constitution or Laws of any State to the Contrary notwithstanding. The Senators and Representatives before mentioned, and the Members of the several State Legislatures, and all executive and judicial Officers, both of the United States and of the several States, shall be bound by Oath or Affirmation, to support this Constitution; but no religious Test shall ever be required as a Qualification to any Office or public Trust under the United States.","by":{"2":"25, 26"}},{"t":"case","label":"Andrus v. Glover Construction Co.","cite":"446 U.S. 608","y":1980,"id":"1979/79-48","sc":1,"by":{"3":"4"},"q":[{"src":"brief","b":3,"text":"[w]here Congress explicitly enumerates certain exceptions.","cite":"446 U.S. 608, 616-617"}]},{"t":"case","label":"Arthur Andersen LLP v. Carlisle","cite":"556 U.S. 624","y":2009,"id":"2008/08-146","sc":1,"by":{"3":"8, 16"},"q":[{"src":"argument","who":"Mr. Shanmugam","text":"But, again, as this Court recognized, for instance, in Arthur Andersen in the context of appeals in the arbitration context, sanctions and fee awards paradigmatically would apply in a situation like this where a party is advancing a frivolous argument and doing that for an improper purpose, namely, for the purpose of establishing appellate jurisdiction where there otherwise would not be any."}]},{"t":"case","label":"Ashcroft v. Iqbal","cite":"556 U.S. 662","y":2009,"id":"2008/07-1015","sc":1,"by":{"3":"13"}},{"t":"case","label":"Boyle v. United Technologies Corp.","cite":"487 U.S. 500","y":1988,"id":"1987/86-492","sc":1,"by":{"3":"19"}},{"t":"case","label":"Bristol-Myers Squibb Co. v. Superior Court","cite":"137 S. Ct. 1773","y":2017,"id":"2016/16-466","sc":1,"by":{"3":"17"}},{"t":"case","label":"Budinich v. Becton Dickinson & Co.","cite":"486 U.S. 196","y":1988,"id":"1987/87-283","sc":1,"by":{"3":"5"}},{"t":"case","label":"City of New York v. BP p.l.c.","cite":"325 F. Supp. 3d 466","y":2018,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/325/466/","by":{"3":"19"},"q":[{"src":"brief","b":3,"text":"ultimately based on the ‘transboundary’ emission of greenhouse gases,","cite":"325 F. Supp. 3d 466, 472"},{"src":"argument","who":"Mr. Sher","text":"And -- and, again, as the same amicus as well as the New York State amici point out, that removal has become a tactic of defendants in a wide range of cases, including environmental regulation, opioids, sub-prime lending in financial institutions and others."}]},{"t":"case","label":"Eisen v. Carlisle & Jacquelin","cite":"417 U.S. 156","y":1974,"id":"1973/73-203","sc":1,"by":{"3":"13"}},{"t":"case","label":"Goodyear Atomic Corp. v. Miller","cite":"486 U.S. 174","y":1988,"id":"1987/86-1172","sc":1,"by":{"3":"10"}},{"t":"case","label":"Henry Schein, Inc. v. Archer & White Sales, Inc.","cite":"139 S. Ct. 524","y":2019,"id":"2018/17-1272","sc":1,"by":{"3":"16"}},{"t":"case","label":"Horne v. Department of Agriculture","cite":"135 S. Ct. 2419","y":2015,"id":"2014/14-275","sc":1,"by":{"3":"17"}},{"t":"case","label":"Jama v. Immigration & Customs Enforcement","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"by":{"3":"10"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"judicial consensus so broad and unquestioned that we must presume Congress knew of and endorsed it.","cite":"543 U. S. 335, 349"}]},{"t":"case","label":"Kakarala v. Wells Fargo Bank, N.A.","cite":"136 S. Ct. 1153","y":2016,"url":"https://www.courtlistener.com/c/S.%20Ct./136/1153/","sc":1,"by":{"3":"6"}},{"t":"case","label":"McCoy v. Louisiana","cite":"138 S. Ct. 1500","y":2018,"id":"2017/16-8255","sc":1,"by":{"3":"17"}},{"t":"case","label":"McKennon v. Nashville Banner Publishing Co.","cite":"513 U.S. 352","y":1995,"id":"1994/93-1543","sc":1,"by":{"3":"16"}},{"t":"case","label":"Microsoft Corp. v. i4i Limited Partnership","cite":"564 U.S. 91","y":2011,"id":"2010/10-290","sc":1,"by":{"3":"9"}},{"t":"case","label":"Mohawk Industries, Inc. v. Carpenter","cite":"558 U.S. 100","y":2009,"id":"2009/08-678","sc":1,"by":{"3":"13"}},{"t":"case","label":"Moore v. Permanente Medical Group, Inc.","cite":"981 F.2d 443","y":1992,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/981/443/","by":{"3":"5"}},{"t":"case","label":"Nichols v. United States","cite":"136 S. Ct. 1113","y":2016,"id":"2015/15-5238","sc":1,"by":{"3":"4"}},{"t":"case","label":"Ortiz v. Jordan","cite":"562 U.S. 180","y":2011,"id":"2010/09-737","sc":1,"by":{"3":"10"}},{"t":"case","label":"Perdue v. Kenny A. ex rel. Winn","cite":"559 U.S. 542","y":2010,"id":"2009/08-970","sc":1,"by":{"3":"17"}},{"t":"case","label":"Pereira v. Sessions","cite":"138 S. Ct. 2105","y":2018,"id":"2017/17-459","sc":1,"by":{"3":"7"}},{"t":"case","label":"Piper v. Chris-Craft Industries, Inc.","cite":"430 U.S. 1","y":1977,"id":"1976/75-353","sc":1,"by":{"3":"17, 18"},"q":[{"src":"brief","b":3,"text":"called for under th[e] unusual circumstances","cite":"430 U.S. at 47 n.34"}]},{"t":"case","label":"Texas Department of Housing & Community Affairs v. Inclusive Communities Project, Inc.","cite":"135 S. Ct. 2507","y":2015,"id":"2014/13-1371","sc":1,"by":{"3":"9"}},{"t":"case","label":"United States v. Keitel","cite":"211 U.S. 370","y":1908,"id":"scdb/1908-028","sc":1,"by":{"3":"13, 14"}},{"t":"case","label":"United States v. Sisson","cite":"399 U.S. 267","y":1970,"id":"1969/305","sc":1,"by":{"3":"14"},"q":[{"src":"brief","b":3,"text":"reveal[ed] a strong current of congressional solicitude for the plight of a criminal defendant exposed to additional expense and anxiety by a government appeal.","cite":"399 U.S. 267, 291, 298"}]},{"t":"case","label":"Wilkie v. Robbins","cite":"551 U.S. 537","y":2007,"id":"2006/06-219","sc":1,"by":{"3":"13"}},{"t":"const","label":"Amendment VI","clauses":[["sixth-trial","Speedy and Public Trial by Jury"],["confrontation","Confrontation Clause"],["counsel","Right to Counsel"]],"text":"In all criminal prosecutions, the accused shall enjoy the right to a speedy and public trial, by an impartial jury of the State and district wherein the crime shall have been committed, which district shall have been previously ascertained by law, and to be informed of the nature and cause of the accusation; to be confronted with the witnesses against him; to have compulsory process for obtaining witnesses in his favor, and to have the Assistance of Counsel for his defence.","by":{"3":"17"}},{"t":"law","label":"Pub. L. No. 105-17","url":"https://www.govinfo.gov/link/plaw/105/public/17","by":{"3":"9"}},{"t":"law","label":"Pub. L. No. 91-644","url":"https://www.govinfo.gov/link/statute/84/1890","by":{"3":"13"}},{"t":"usc","label":"9 U.S.C. § 3","url":"https://www.law.cornell.edu/uscode/text/9/3","by":{"3":"8"}},{"t":"usc","label":"9 U.S.C. § 16","url":"https://www.law.cornell.edu/uscode/text/9/16","by":{"3":"8"}},{"t":"usc","label":"28 U.S.C. § 2106","url":"https://www.law.cornell.edu/uscode/text/28/2106","by":{"3":"8"}}]};